L["|cffffffffHover a frame, then hold |r|cff55ff55CTRL + Left-Click|r|cffffffff to anchor.  |  Right-Click or Escape cancels.|r"] = "|cffffffffPasa el cursor sobre un marco y mantén |r|cff55ff55CTRL + clic izquierdo|r|cffffffff para anclar.  |  Clic derecho o Escape cancela.|r"
