L["A %s in your group can provide this."] = "Un %s en tu grupo puede proporcionar esto."
L["A calmer setup command center: start with movement, frames, group frames, or a safe profile import."] = "Un centro de configuración más tranquilo: empieza moviendo marcos, ajustando marcos, marcos de grupo o importando un perfil seguro."
L["Active Spell Indicators:"] = "Indicadores de hechizos activos:"
L["Add menu scroll edge bounce."] = "Añadido rebote en los bordes del scroll del menú."
L["Add Spell..."] = "Añadir hechizo..."
L["Added and refined the Menu2 search module."] = "Añadido y refinado el módulo de búsqueda Menu2."
L["Added backend compatibility hardening across MSUF modules."] = "Añadido endurecimiento de compatibilidad backend en módulos MSUF."
L["Added centralized font registry support for the unit frame runtime."] = "Añadido registro centralizado de fuentes para la runtime de marcos de unidad."
L["Added class-colored bar background support across unit and group frames."] = "Añadido soporte de fondo de barra con color de clase en marcos de unidad y grupo."
L["Added core swap recolor runtime support."] = "Añadido soporte runtime para recolor de core swap."
L["Added Focus Target frame support across unit settings, edit mode, menu previews, copy targets, text options, icons, and runtime refreshes."] = "Añadido soporte para el marco Objetivo del foco en ajustes de unidad, modo de edición, vistas previas, destinos de copia, opciones de texto, iconos y actualizaciones en runtime."
L["Added improved on/off switch visuals."] = "Añadidos visuales mejorados para interruptores on/off."
L["Added more Menu2 cards and refined menu structure."] = "Añadidas más tarjetas Menu2 y refinada la estructura del menú."
L["Added more Menu2 cards to group and unit sections."] = "Añadidas más tarjetas Menu2 a secciones de grupo y unidad."
L["Added new Menu2 search module and improved search/guidance text."] = "Añadido nuevo módulo de búsqueda Menu2 y mejorado el texto de búsqueda/guía."
L["Added new UI/media assets for switches and rounded/superellipse visuals."] = "Añadidos nuevos assets UI/media para interruptores y visuales redondeados/superellipse."
L["Added raid group number display next to unit names."] = "Añadida visualización del número de grupo de banda junto a nombres."
L["Added redesigned Menu2 card layout across unit, group, aura, indicator, bar, and advanced pages."] = "Añadido layout rediseñado de tarjetas Menu2 en páginas de unidad, grupo, aura, indicador, barras y avanzado."
L["Added Rounded Frames with per-surface controls for unit frames, group frames, bars, highlights, overlays, absorbs, and indicators."] = "Añadidos Marcos redondeados con controles por superficie para marcos de unidad, marcos de grupo, barras, resaltados, overlays, absorciones e indicadores."
L["Added rounded mask media for the live unit/group frames and Menu2 preview."] = "Añadidos medios de máscara redondeada para marcos en vivo y vista previa Menu2."
L["Added Rounded Texture controls under Global Style > Bars with per-surface toggles, search coverage, localization, preview support, and a reload prompt."] = "Añadidos controles de Textura redondeada en Estilo global > Barras con toggles por superficie, búsqueda, localización, vista previa y aviso de recarga."
