L["Editing:"] = "Editando:"
L["EM_HELP_BTN"] = "? Ayuda"
L["EM_HELP_BTN_TIP"] = "Abre la configuración guiada completa de MSUF\nen el capítulo del modo de edición."
L["EM_HELP_CDM"] = "|cff60a5ffCDM|r alterna el ancla global de Essential Cooldown Manager. |cff60a5ffAnchor|r abre el selector de ancla; pasa el cursor sobre un marco con nombre, mantén Ctrl y haz clic izquierdo para usarlo como ancla global. Elegir un ancla personalizada desactiva CDM."
L["EM_HELP_COPYTO"] = "En ventanas de unidad y barras de lanzamiento, |cff60a5ffCopy To|r copia los ajustes de la ventana actual a otro destino. La copia de marcos de unidad conserva la posición y el ancla del destino; la copia de barras conserva los desplazamientos X/Y del destino."
L["EM_HELP_DRAG"] = "Mantén pulsado el botón izquierdo sobre una superposición de movedor y arrástrala. El marco real sigue al movedor, y la lectura X/Y bajo la superposición muestra el desplazamiento actual en pantalla. Suelta el botón para guardar la posición."
L["EM_HELP_EXIT"] = "|cff60a5ffExit|r sale del modo de edición y conserva los cambios actuales. Entrar en combate también sale del modo de edición. Escape cierra o cancela la ventana emergente; el botón Exit del HUD es la forma normal de salir."
L["EM_HELP_NUDGE"] = "Las flechas mueven el objetivo activo. Prioridad: tirador de vista previa seleccionado, ventana de barra abierta, ventana de aura abierta y luego el marco de unidad seleccionado. Tamaño del paso: 1 px, Mayús = 5 px, Ctrl = 10 px, Alt = paso actual de la cuadrícula."
L["EM_HELP_OPACITY"] = "Desplaza el control |cff60a5ffBG ##%|r para cambiar solo la opacidad del fondo del modo de edición. No cambia la alfa del marco de unidad ni la visibilidad guardada."
L["EM_HELP_POPUP"] = "Clic izquierdo en un movedor sin arrastrar abre su ventana de edición. Las ventanas de unidad editan tamaño, posición, anclas de texto, ajustes de poder separado y opciones de copiar a unidad. Los movedores de barras y auras abren sus propias ventanas enfocadas."
L["EM_HELP_PREVIEW"] = "|cff60a5ffPreview|r alterna datos de marcador para objetivo, foco, objetivo del objetivo, mascota, jefes y vistas de barras cuando no existen unidades y el modo de edición está activo. |cff60a5ffAuras|r alterna iconos de vista previa de auras y cajas de movedores de auras."
L["EM_HELP_SNAP"] = "La cuadrícula es una guía visual. Clic izquierdo en |cff60a5ffGrid ##px|r alterna las líneas; desplazar cambia el espaciado. |cff60a5ffSnap|r es independiente: al activarlo, los movedores arrastrados se ajustan al centro de la pantalla o a bordes/centros de otros movedores visibles, con guías naranjas."
L["EM_HELP_TITLE"] = "Modo de edición - Referencia rápida"
L["EM_HELP_UNDO"] = "|cff60a5ffUndo|r y |cff60a5ffRedo|r restauran cambios recientes del modo de edición capturados antes de arrastres, ajustes con flechas y cambios de ventanas. |cff60a5ffCancel All|r pide confirmación, restaura la instantánea previa al modo de edición y luego sale."
