L["Button"] = "Botón"
L["Can MSUF hide debuffs with a blacklist?"] = "¿Puede MSUF ocultar perjuicios con una lista negra?"
L["Checked categories hide MSUF custom buff icons only. Blizzard-rendered buffs bypass this list, so Skyfury or Earth Shield can still appear while Use Blizzard: Buffs is enabled."] = "Las categorias marcadas solo ocultan iconos de beneficios personalizados de MSUF. Los beneficios renderizados por Blizzard omiten esta lista, asi que Skyfury o Earth Shield pueden seguir apareciendo mientras Usar Blizzard: Beneficios este activado."
L["Checked categories hide MSUF custom debuff icons only. Blizzard-rendered debuffs bypass this list while Use Blizzard: Debuffs is enabled."] = "Las categorias marcadas solo ocultan iconos de perjuicios personalizados de MSUF. Los perjuicios renderizados por Blizzard omiten esta lista mientras Usar Blizzard: Perjuicios este activado."
