L["Open Group Frames > Health & Text. It controls health colors, bars, power bar, text, dispel overlay, debuff stripe, and range fade. Heal prediction is in Global Style > Bars > Absorb Display."] = "Abre Marcos de grupo > Salud y texto. Controla colores de salud, barras, barra de poder, texto, overlay de disipación, franja de perjuicios y desvanecimiento por alcance. La predicción de sanación está en Estilo global > Barras > Visualización de absorción."
L["Open Unit Auras > Global Ignore List. It can hide predefined aura categories for all unit frames, or per unit after enabling Override for this unit. MSUF does not currently have an ElvUI-style freeform spell-ID blacklist for arbitrary debuffs."] = "Abre Auras de unidad > Lista global de ignorados. Puede ocultar categorías de auras predefinidas para todos los marcos de unidad, o por unidad tras activar Sobrescribir para esta unidad. MSUF no tiene actualmente una lista negra libre de IDs de hechizo al estilo ElvUI para perjuicios arbitrarios."
L["Open this section to enable or disable rounded frame textures and its per-surface toggles."] = "Abre esta seccion para activar o desactivar las texturas de marco redondeado y sus interruptores por superficie."
L["Opens: Unit Auras > Global Ignore List"] = "Abre: Auras de unidad > Lista global de ignorados"
