L["When enabled, WoW owns buff icons. MSUF hide categories and custom buff positioning do not filter Blizzard-rendered buffs, so Skyfury or Earth Shield can still appear."] = "Cuando esta activado, WoW controla los iconos de beneficios. Las categorias ocultas de MSUF y la posicion personalizada de beneficios no filtran los beneficios renderizados por Blizzard, asi que Skyfury o Earth Shield pueden seguir apareciendo."
L["When enabled, WoW owns debuff icons. MSUF hide categories and custom debuff positioning do not filter Blizzard-rendered debuffs."] = "Cuando esta activado, WoW controla los iconos de perjuicios. Las categorias ocultas de MSUF y la posicion personalizada de perjuicios no filtran los perjuicios renderizados por Blizzard."
L["When enabled, WoW owns defensive icons. MSUF custom positioning and styling apply only when this is off or the renderer is MSUF Custom."] = "Cuando esta activado, WoW controla los iconos defensivos. La posicion y el estilo personalizados de MSUF solo se aplican cuando esto esta desactivado o el renderizador es MSUF Custom."
