L["Keep tanks and manually pinned group members in one stable strip without removing them from the normal Party or Raid frames."] = "Mantén a los tanques y miembros fijados manualmente en una franja estable sin quitarlos de los marcos normales de grupo o banda."
L["Profile-wide layout · character-specific pins · available in parties and raids · inherits the active group-frame appearance and click-cast behavior."] = "Diseño para todo el perfil · fijaciones por personaje · disponible en grupos y bandas · hereda el aspecto y el lanzamiento con clic de los marcos de grupo activos."
