L["Hover an MSUF Party, Raid, or Priority frame and press this key to pin or unpin that player."] = "Pasa el cursor sobre un marco de grupo, banda o prioritario de MSUF y pulsa esta tecla para fijar o soltar al jugador."
L["No manual pins yet. While grouped, hover an MSUF Party, Raid, or Priority frame, then press your hotkey."] = "Aún no hay fijaciones manuales. En grupo, pasa el cursor sobre un marco de grupo, banda o prioritario de MSUF y pulsa tu tecla."
L["Use the hover hotkey above to add or remove players."] = "Usa la tecla al pasar el cursor para añadir o eliminar jugadores."
