L["Custom Aura tracking on Unitframes"] = "Seguimiento de aura personalizado en Unitframes"
L["Build up to three frame-specific Custom lanes on Player, Target, Focus and Boss, then whitelist exact buff or debuff SpellIDs."] = "Construya hasta tres carriles personalizados específicos del cuadro en Jugador, Objetivo, Enfoque y Jefe, luego incluya en la lista blanca los ID de hechizo exactos de mejora o desventaja."
L["Your MSUF frames can act as focused WeakAura-style trackers with icons, timers, duration bars and full-frame tint, border, glow or pulse effects."] = "Sus marcos MSUF pueden actuar como rastreadores enfocados estilo WeakAura con íconos, temporizadores, barras de duración y efectos de tinte, borde, brillo o pulso de fotograma completo."
L["three Custom Aura trackers per supported Unitframe, exact spell whitelists and full-frame effects"] = "tres rastreadores de aura personalizados por unidad de fotograma compatible, listas blancas de hechizos exactas y efectos de fotograma completo"
L["Build a Custom tracker"] = "Crear un rastreador personalizado"
L["Auras3: a full Aura menu rework"] = "Auras3: una revisión completa del menú Aura"
L["The 5.71 Auras2 page has been rebuilt as Auras3, with separate Unitframe and Group workspaces plus Buff, Debuff and Custom lanes."] = "La página 5.71 Auras2 se ha reconstruido como Auras3, con espacios de trabajo Unitframe y Group separados, además de carriles Buff, Debuff y Custom."
L["Each lane gets its own live preview, layout, growth, sorting, filters, blacklist or whitelist, cooldown text, swipe, stacks and duration bars."] = "Cada carril tiene su propia vista previa en vivo, diseño, crecimiento, clasificación, filtros, lista negra o lista blanca, texto de tiempo de espera, deslizamiento, pilas y barras de duración."
L["the rebuilt Auras3 workspace, lane-specific previews, layouts, sorting, filters and styling"] = "el espacio de trabajo reconstruido de Auras3, vistas previas, diseños, clasificación, filtros y estilos específicos de carriles"
L["Explore the Aura rework"] = "Explora la reelaboración del Aura"
L["Adaptive Party and Raid layouts"] = "Diseños adaptables de grupo y raid"
L["Group frames gained smarter layouts, stronger status handling, range behavior and clearer health feedback."] = "Los marcos de grupo obtuvieron diseños más inteligentes, un manejo de estado más sólido, comportamiento de alcance y comentarios de salud más claros."
L["You can make one group setup adapt more cleanly between party, raid and encounter needs."] = "Puedes hacer que la configuración de un grupo se adapte más claramente entre las necesidades del grupo, la incursión y el encuentro."
L["adaptive group layouts, range behavior and group status controls"] = "Diseños de grupo adaptables, comportamiento de rango y controles de estado de grupo."
L["Open Group Layout"] = "Diseño de grupo abierto"
L["New health values and text formats"] = "Nuevos valores de salud y formatos de texto."
L["Health text can show abbreviated or full values with more consistent formatting across unit and group frames."] = "El texto de salud puede mostrar valores abreviados o completos con un formato más consistente en marcos de unidades y grupos."
L["You can choose compact readability or exact numbers without giving up the layout you already use."] = "Puede elegir legibilidad compacta o números exactos sin renunciar al diseño que ya utiliza."
L["the new health abbreviations, full values and text-format options"] = "las nuevas abreviaturas de salud, valores completos y opciones de formato de texto"
L["Review Group Bars"] = "Revisar barras de grupo"
L["More flexible class resources"] = "Recursos de clase más flexibles"
L["Class resources gained detached layouts, additional shapes and finer per-slot and full-state colors."] = "Los recursos de clase obtuvieron diseños independientes, formas adicionales y colores más finos por ranura y de estado completo."
L["You can move class information where your eyes already are and make important states easier to read."] = "Puede mover la información de la clase donde ya están sus ojos y hacer que los estados importantes sean más fáciles de leer."
L["detached class resources, new shapes and per-state colors"] = "Recursos de clases independientes, nuevas formas y colores por estado."
L["Configure Class Resources"] = "Configurar recursos de clase"
L["Cast target text"] = "Transmitir texto de destino"
L["Target, Focus and Boss cast bars can now show who the current spell is targeting, with dedicated text styling."] = "Las barras de lanzamiento de Objetivo, Enfoque y Jefe ahora pueden mostrar a quién apunta el hechizo actual, con un estilo de texto dedicado."
L["You can identify the destination of an important cast without shifting attention away from the cast bar."] = "Puede identificar el destino de un reparto importante sin desviar la atención de la barra de reparto."
L["cast-target names and their text styling on Target, Focus and Boss frames"] = "nombres de objetivos de reparto y su estilo de texto en los marcos de Objetivo, Enfoque y Jefe"
