L["Shows tick separators on the Player castbar while channeling.\n\nSupported spells use their actual tick count, including supported talent and channel-duration changes. Unsupported channels keep five evenly spaced fallback lines. Custom channel tick settings override the automatic layout.\n\nThe markers are event-driven and add no recurring channel polling."] = "Muestra separadores de ticks en la barra de transmisión del jugador mientras se canaliza.\n\nLos hechizos admitidos utilizan su recuento de ticks real, incluidos los talentos admitidos y los cambios de duración del canal. Los canales no compatibles mantienen cinco líneas de reserva espaciadas uniformemente. La configuración de marca de canal personalizada anula el diseño automático.\n\nLos marcadores se basan en eventos y no agregan sondeos de canales recurrentes."
