L["Open Colors > Bar Gradient Colors for separate Health and Power gradient colors in the selected Bars scope."] = "Abra Colores > Colores de degradado de barra para obtener colores de degradado de salud y potencia separados en el alcance de barras seleccionado."
L["Open Colors > Group Frame Colors for shared Party, Raid and Mythic Raid colors."] = "Abre Colores > Colores de marco de grupo para los colores compartidos de Grupo, Incursión y Incursión mítica."
L["Open Edit Mode and move Party Frames"] = "Abra el modo de edición y mueva los marcos de fiesta"
L["Open Group Frames > Auras for Buff/Debuff filters, lists, visibility, and layout. For text, cooldowns, stacks, and duration bars use Appearance > Auras and select Party or Raid scope."] = "Abra Marcos de grupo > Auras para filtros, listas, visibilidad y diseño de mejoras/desventajas. Para texto, tiempos de reutilización, acumulaciones y barras de duración, usa Apariencia > Auras y selecciona Grupo o Alcance de incursión."
L["Open Group Frames > Layout. Text, Resource Bar, and Range Fade are arranged beside Frame Basics and Transparency. Dispel Overlay and Debuff Stripe are on the Dispel Overlay page. Heal prediction is in Global Style > Bars > Absorb Display."] = "Abra Marcos de grupo > Diseño. El texto, la barra de recursos y el desvanecimiento de rango están organizados junto a Conceptos básicos del marco y Transparencia. Disipar superposición y Debuff Stripe se encuentran en la página Disipar superposición. La predicción de curación está en Estilo global > Barras > Absorber pantalla."
L["Open it and choose a different value."] = "Ábrelo y elige un valor diferente."
L["Open the affected UnitFrame > Auras > Debuffs and enable the native Dispellable rule. For Party/Raid use Group Frames > Auras > Debuffs."] = "Abra el UnitFrame afectado > Auras > Desventajas y habilite la regla nativa Disipable. Para grupo/incursión, utiliza Marcos de grupo > Auras > Desventajas."
L["Open the affected UnitFrame > Auras > Debuffs and use its frame-specific SpellID blacklist. Group exclusions live directly in Group Frames > Auras > Debuffs."] = "Abra el UnitFrame afectado > Auras > Debuffs y use su lista negra SpellID específica del marco. Las exclusiones de grupo se encuentran directamente en Marcos de grupo > Auras > Desventajas."
L["Open the affected UnitFrame > Auras and choose Buffs or Debuffs. Check its frame-specific Blizzard filters, blacklist, enabled state, and icon cap. For Party/Raid use Group Frames > Auras."] = "Abra el UnitFrame afectado > Auras y elija Buffs o Debuffs. Verifique los filtros de Blizzard específicos del marco, la lista negra, el estado habilitado y el límite del icono. Para Grupo/Incursión, utiliza Marcos de grupo > Auras."
L["Open the affected UnitFrame > Auras for visibility, layout, filters, and blacklists. Use Appearance > Auras for scope-aware cooldown, stack, duration-bar, and icon styling."] = "Abra el UnitFrame > Auras afectado para obtener visibilidad, diseño, filtros y listas negras. Utilice Apariencia > Auras para el enfriamiento, la pila, la barra de duración y el estilo de íconos según el alcance."
L["Open the frame and expand Auras. Buffs and Debuffs contain their own Blizzard filters and blacklists; Custom 1-3 contains its own whitelist. There is no separate Filter tab."] = "Abra el marco y expanda Auras. Las ventajas y desventajas contienen sus propios filtros y listas negras de Blizzard; Personalizado 1-3 contiene su propia lista blanca. No hay una pestaña Filtro separada."
L["Open the matching color section below."] = "Abra la sección de colores coincidentes a continuación."
L["Opens Buff styling for this frame. Spell choice, placement, size, layer, and frame highlight stay unique to this indicator."] = "Abre el estilo Buff para este marco. La elección del hechizo, la ubicación, el tamaño, la capa y el resaltado del marco siguen siendo exclusivos de este indicador."
